const files = {"index.html":"<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#f8c84e\">\n  <meta name=\"description\" content=\"Upload a cat or dog photo and add a silly little pet thought or speech bubble.\">\n  <title>Pet Thought Bubbler</title>\n  <link rel=\"stylesheet\" href=\"styles.css\">\n  <script src=\"https://cdn.jsdelivr.net/npm/@tensorflow/tfjs@4.22.0/dist/tf.min.js\" defer></script>\n  <script src=\"https://cdn.jsdelivr.net/npm/@tensorflow-models/coco-ssd@2.2.3/dist/coco-ssd.min.js\" defer></script>\n</head>\n<body>\n  <main class=\"app\">\n    <section class=\"studio\" aria-labelledby=\"appTitle\">\n      <div class=\"workspace\">\n        <div class=\"brand-row\">\n          <div>\n            <p class=\"eyebrow\">Pet Thought Bubbler</p>\n            <h1 id=\"appTitle\">What is this tiny roommate thinking?</h1>\n          </div>\n          <button class=\"icon-button\" id=\"shuffleAllBtn\" type=\"button\" aria-label=\"Surprise me\" title=\"Surprise me\">?</button>\n        </div>\n\n        <div class=\"canvas-wrap\">\n          <canvas id=\"petCanvas\" width=\"1200\" height=\"900\" aria-label=\"Pet photo with caption bubble\"></canvas>\n          <div class=\"empty-state\" id=\"emptyState\">\n            <div class=\"empty-mark\" aria-hidden=\"true\">\n              <span></span>\n              <i></i>\n            </div>\n            <p>Drop in a cat or dog photo.</p>\n          </div>\n        </div>\n      </div>\n\n      <aside class=\"controls\" aria-label=\"Pet bubble controls\">\n        <label class=\"upload-zone\" id=\"dropZone\">\n          <input id=\"photoInput\" type=\"file\" accept=\"image/*\">\n          <span>Choose Photo</span>\n          <small>JPG, PNG, GIF, or a fresh camera shot</small>\n        </label>\n        <input id=\"cameraInput\" class=\"visually-hidden\" type=\"file\" accept=\"image/*\" capture=\"environment\">\n        <label class=\"camera-button\" id=\"cameraBtn\" for=\"cameraInput\" role=\"button\" tabindex=\"0\" aria-label=\"Open camera\">\n          <span aria-hidden=\"true\"></span>\n          Camera\n        </label>\n        <p class=\"detector-status\" id=\"detectorStatus\" aria-live=\"polite\">Ready to spot cats and dogs.</p>\n\n        <div class=\"control-block\">\n          <span class=\"label\">Pet</span>\n          <div class=\"segmented\" role=\"group\" aria-label=\"Pet type\">\n            <button class=\"active\" data-pet=\"cat\" type=\"button\">Cat</button>\n            <button data-pet=\"dog\" type=\"button\">Dog</button>\n            <button data-pet=\"either\" type=\"button\">Mystery</button>\n          </div>\n        </div>\n\n        <div class=\"control-block\">\n          <span class=\"label\">Bubble</span>\n          <div class=\"segmented\" role=\"group\" aria-label=\"Bubble type\">\n            <button class=\"active\" data-bubble=\"thought\" type=\"button\">Think</button>\n            <button data-bubble=\"speech\" type=\"button\">Say</button>\n          </div>\n        </div>\n\n        <div class=\"control-block\">\n          <span class=\"label\">Mood</span>\n          <select id=\"moodSelect\" aria-label=\"Phrase mood\">\n            <option value=\"random\">All the silliness</option>\n            <option value=\"food\">Food crimes</option>\n            <option value=\"royalty\">Tiny royalty</option>\n            <option value=\"chaos\">Gentle chaos</option>\n            <option value=\"nap\">Nap science</option>\n            <option value=\"dramatic\">Very dramatic</option>\n            <option value=\"compliment\">Sweet little compliments</option>\n          </select>\n        </div>\n\n        <div class=\"control-block photo-only\" id=\"phraseBlock\">\n          <span class=\"label\">Phrase</span>\n          <textarea id=\"phraseInput\" rows=\"3\" maxlength=\"110\" aria-label=\"Pet phrase\"></textarea>\n          <div class=\"button-grid\">\n            <button class=\"btn primary\" id=\"phraseBtn\" type=\"button\">New Phrase</button>\n            <button class=\"btn\" id=\"shortBtn\" type=\"button\">Short</button>\n          </div>\n        </div>\n\n        <div class=\"control-block\">\n          <span class=\"label\">Bubble Spot</span>\n          <div class=\"position-grid\" role=\"group\" aria-label=\"Bubble position\">\n            <button class=\"auto active\" data-position=\"auto\" type=\"button\" aria-label=\"Auto align near pet head\">Auto</button>\n            <button data-position=\"top-left\" type=\"button\" aria-label=\"Top left\"></button>\n            <button data-position=\"top-right\" type=\"button\" aria-label=\"Top right\"></button>\n            <button data-position=\"bottom-left\" type=\"button\" aria-label=\"Bottom left\"></button>\n            <button data-position=\"bottom-right\" type=\"button\" aria-label=\"Bottom right\"></button>\n          </div>\n        </div>\n\n        <div class=\"control-block sliders\">\n          <label>\n            <span>Bubble Size</span>\n            <input id=\"sizeRange\" type=\"range\" min=\"72\" max=\"132\" value=\"100\">\n          </label>\n          <label>\n            <span>Text Size</span>\n            <input id=\"textRange\" type=\"range\" min=\"70\" max=\"125\" value=\"100\">\n          </label>\n        </div>\n\n        <div class=\"actions\">\n          <button class=\"btn primary\" id=\"downloadBtn\" type=\"button\">Download Image</button>\n          <button class=\"btn\" id=\"clearBtn\" type=\"button\">Clear Photo</button>\n          <button class=\"btn primary photo-only\" id=\"sharePhotoBtn\" type=\"button\">Share Photo</button>\n          <button class=\"btn\" id=\"shareAppBtn\" type=\"button\">Share App</button>\n        </div>\n      </aside>\n    </section>\n  </main>\n  <script type=\"module\" src=\"game.js\"></script>\n</body>\n</html>\n","styles.css":":root {\n  --ink: #241f21;\n  --soft-ink: #625c56;\n  --paper: #fffaf0;\n  --panel: #ffffff;\n  --line: #ded4c3;\n  --yellow: #f8c84e;\n  --coral: #f37b62;\n  --teal: #2f9f95;\n  --blue: #4f8fcf;\n  --shadow: 0 24px 68px rgba(36, 31, 33, .13);\n  --shadow-soft: 0 12px 30px rgba(36, 31, 33, .1);\n}\n\n* { box-sizing: border-box; }\nhtml { min-height: 100%; background: var(--paper); }\nbody {\n  min-height: 100%;\n  margin: 0;\n  color: var(--ink);\n  background:\n    radial-gradient(circle at 20% 18%, rgba(248, 200, 78, .36), transparent 30%),\n    radial-gradient(circle at 86% 74%, rgba(79, 143, 207, .22), transparent 26%),\n    linear-gradient(135deg, #fffaf0, #f4eee4 44%, #eef7f4);\n  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", Arial, sans-serif;\n  text-rendering: geometricPrecision;\n}\n\nbutton, input, select, textarea { font: inherit; }\nbutton, select, textarea, input[type=\"range\"] { color: inherit; }\nbutton,\n.camera-button {\n  border: 0;\n  cursor: pointer;\n  transition: transform .16s ease, filter .16s ease, box-shadow .16s ease, background-color .16s ease, border-color .16s ease;\n}\nbutton:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible, .camera-button:focus-visible {\n  outline: 3px solid rgba(47, 159, 149, .45);\n  outline-offset: 3px;\n}\n.visually-hidden {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip: rect(0 0 0 0);\n  clip-path: inset(50%);\n  white-space: nowrap;\n}\n\n.app {\n  min-height: 100dvh;\n  padding: max(20px, env(safe-area-inset-top)) max(20px, env(safe-area-inset-right)) max(20px, env(safe-area-inset-bottom)) max(20px, env(safe-area-inset-left));\n  display: grid;\n  place-items: center;\n}\n\n.studio {\n  width: min(1280px, 100%);\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) 360px;\n  gap: 18px;\n  align-items: stretch;\n}\n\n.workspace, .controls {\n  border: 1px solid rgba(222, 212, 195, .74);\n  border-radius: 8px;\n  background: rgba(255, 255, 255, .9);\n  box-shadow: var(--shadow);\n  backdrop-filter: blur(18px);\n}\n\n.workspace {\n  min-width: 0;\n  padding: clamp(16px, 2vw, 24px);\n}\n\n.brand-row {\n  display: flex;\n  justify-content: space-between;\n  gap: 18px;\n  align-items: start;\n  margin-bottom: 14px;\n}\n\n.eyebrow {\n  margin: 0 0 7px;\n  color: #8c552d;\n  font-size: 13px;\n  font-weight: 800;\n  letter-spacing: 0;\n  text-transform: uppercase;\n}\n\nh1 {\n  max-width: 760px;\n  margin: 0;\n  font-size: clamp(32px, 5vw, 66px);\n  line-height: .96;\n  letter-spacing: 0;\n}\n\n.icon-button {\n  flex: 0 0 auto;\n  width: 46px;\n  height: 46px;\n  border-radius: 50%;\n  color: #181512;\n  background: var(--yellow);\n  box-shadow: inset 0 -3px rgba(150, 103, 14, .22), 0 8px 20px rgba(248, 200, 78, .25);\n  font-size: 24px;\n  font-weight: 900;\n}\n\n.canvas-wrap {\n  position: relative;\n  overflow: hidden;\n  border: 2px solid rgba(45, 39, 40, .88);\n  border-radius: 8px;\n  background:\n    linear-gradient(45deg, #eadfcd 25%, transparent 25%),\n    linear-gradient(-45deg, #eadfcd 25%, transparent 25%),\n    linear-gradient(45deg, transparent 75%, #eadfcd 75%),\n    linear-gradient(-45deg, transparent 75%, #eadfcd 75%),\n    #f7f0e5;\n  background-position: 0 0, 0 12px, 12px -12px, -12px 0;\n  background-size: 24px 24px;\n  aspect-ratio: 4 / 3;\n  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .54), var(--shadow-soft);\n}\n\ncanvas {\n  width: 100%;\n  height: 100%;\n  display: block;\n}\n\n.empty-state {\n  position: absolute;\n  inset: 0;\n  display: grid;\n  place-content: center;\n  justify-items: center;\n  gap: 16px;\n  padding: 26px;\n  text-align: center;\n  color: var(--soft-ink);\n  pointer-events: none;\n  transition: opacity .18s ease;\n}\n.empty-state.hidden { display: none; }\n.empty-state p {\n  margin: 0;\n  font-size: clamp(19px, 3vw, 26px);\n  font-weight: 850;\n}\n.empty-mark {\n  position: relative;\n  width: 140px;\n  height: 110px;\n  border: 4px solid #2d2728;\n  border-radius: 42px 42px 30px 30px;\n  background: #fff;\n}\n.empty-mark span,\n.empty-mark i {\n  position: absolute;\n  top: 42px;\n  width: 14px;\n  height: 14px;\n  border-radius: 50%;\n  background: #2d2728;\n}\n.empty-mark span { left: 42px; }\n.empty-mark i { right: 42px; }\n.empty-mark::before,\n.empty-mark::after {\n  content: \"\";\n  position: absolute;\n  top: -22px;\n  width: 42px;\n  height: 42px;\n  border: 4px solid #2d2728;\n  border-bottom: 0;\n  background: #fff;\n}\n.empty-mark::before {\n  left: 13px;\n  transform: rotate(32deg);\n  border-radius: 12px 28px 0 0;\n}\n.empty-mark::after {\n  right: 13px;\n  transform: rotate(-32deg);\n  border-radius: 28px 12px 0 0;\n}\n\n.controls {\n  padding: 18px;\n  display: flex;\n  flex-direction: column;\n  gap: 13px;\n}\n.app:not(.has-photo) .photo-only {\n  display: none;\n}\n\n.upload-zone {\n  min-height: 118px;\n  padding: 16px;\n  display: grid;\n  place-content: center;\n  gap: 6px;\n  text-align: center;\n  border: 2px dashed rgba(171, 137, 80, .66);\n  border-radius: 8px;\n  background: linear-gradient(180deg, #fff9ea, #fff4d9);\n  cursor: pointer;\n  box-shadow: inset 0 1px rgba(255, 255, 255, .8);\n}\n.upload-zone.dragover {\n  border-color: var(--teal);\n  background: #eaf8f5;\n}\n.upload-zone input { display: none; }\n.upload-zone span,\n.label {\n  font-weight: 900;\n}\n.upload-zone small {\n  color: var(--soft-ink);\n  font-size: 13px;\n}\n.camera-button {\n  min-height: 48px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 10px;\n  border-radius: 8px;\n  color: #fff;\n  background: linear-gradient(180deg, #5a9edb, #3f85c8);\n  font-weight: 900;\n  box-shadow: inset 0 -3px rgba(21, 76, 129, .32), var(--shadow-soft);\n}\n.camera-button span {\n  position: relative;\n  width: 24px;\n  height: 18px;\n  border: 3px solid currentColor;\n  border-radius: 5px;\n}\n.camera-button span::before {\n  content: \"\";\n  position: absolute;\n  left: 5px;\n  top: 3px;\n  width: 8px;\n  height: 8px;\n  border: 2px solid currentColor;\n  border-radius: 50%;\n}\n.camera-button span::after {\n  content: \"\";\n  position: absolute;\n  left: 4px;\n  top: -7px;\n  width: 8px;\n  height: 5px;\n  border-radius: 3px 3px 0 0;\n  background: currentColor;\n}\n.detector-status {\n  min-height: 38px;\n  margin: -4px 0 0;\n  padding: 9px 11px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  color: var(--soft-ink);\n  background: rgba(255, 254, 250, .9);\n  font-size: 13px;\n  font-weight: 800;\n  line-height: 1.25;\n}\n.detector-status.warning {\n  color: #7c2e24;\n  background: #fff0ec;\n  border-color: #edb8ad;\n}\n.detector-status.success {\n  color: #176b63;\n  background: #eaf8f5;\n  border-color: #9bd7d0;\n}\n\n.control-block {\n  display: grid;\n  gap: 8px;\n}\n.label {\n  font-size: 13px;\n  text-transform: uppercase;\n  letter-spacing: 0;\n  color: #7d6244;\n}\n\n.segmented,\n.button-grid,\n.actions {\n  display: grid;\n  gap: 8px;\n}\n.segmented {\n  grid-template-columns: repeat(3, 1fr);\n  padding: 4px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: #f6efe4;\n  box-shadow: inset 0 1px rgba(255, 255, 255, .76);\n}\n.segmented button,\n.btn,\nselect,\ntextarea,\n.position-grid button {\n  border-radius: 8px;\n}\n.segmented button {\n  min-height: 40px;\n  background: transparent;\n  color: var(--soft-ink);\n  font-weight: 800;\n}\n.segmented button.active {\n  color: #fff;\n  background: #2d2728;\n  box-shadow: 0 5px 14px rgba(36, 31, 33, .16);\n}\n\nselect,\ntextarea {\n  width: 100%;\n  border: 1px solid var(--line);\n  background: #fffefa;\n}\nselect {\n  min-height: 44px;\n  padding: 0 12px;\n  font-weight: 760;\n}\ntextarea {\n  resize: vertical;\n  min-height: 86px;\n  padding: 12px;\n  line-height: 1.35;\n  font-weight: 750;\n  transition: border-color .16s ease, box-shadow .16s ease, background-color .16s ease;\n}\nselect:focus,\ntextarea:focus {\n  border-color: rgba(47, 159, 149, .55);\n  box-shadow: 0 0 0 4px rgba(47, 159, 149, .11);\n}\n\n.button-grid {\n  grid-template-columns: 1fr 90px;\n}\n.btn {\n  min-height: 44px;\n  padding: 10px 14px;\n  background: linear-gradient(180deg, #eee5d8, #e3d6c6);\n  color: #27211f;\n  font-weight: 900;\n  box-shadow: inset 0 -3px rgba(36, 31, 33, .1), var(--shadow-soft);\n}\n.btn.primary {\n  color: #fff;\n  background: linear-gradient(180deg, #39aea4, #2d978e);\n  box-shadow: inset 0 -3px rgba(11, 80, 74, .28), 0 10px 22px rgba(47, 159, 149, .18);\n}\n.btn:hover,\n.icon-button:hover,\n.position-grid button:hover,\n.camera-button:hover,\n.upload-zone:hover {\n  transform: translateY(-1px);\n  filter: brightness(1.03);\n}\n.btn:active,\n.icon-button:active,\n.camera-button:active,\n.segmented button:active,\n.position-grid button:active {\n  transform: translateY(0);\n}\n\n.position-grid {\n  display: grid;\n  grid-template-columns: 68px repeat(2, 42px);\n  gap: 8px;\n}\n.position-grid button {\n  position: relative;\n  width: 42px;\n  height: 42px;\n  border: 1px solid var(--line);\n  background: linear-gradient(180deg, #faf3e8, #efe5d7);\n  box-shadow: inset 0 1px rgba(255, 255, 255, .72);\n}\n.position-grid button.auto {\n  width: 68px;\n  color: var(--soft-ink);\n  font-size: 13px;\n  font-weight: 900;\n}\n.position-grid button::after {\n  content: \"\";\n  position: absolute;\n  width: 15px;\n  height: 15px;\n  border-radius: 50%;\n  background: var(--coral);\n}\n.position-grid button.auto::after { display: none; }\n.position-grid [data-position=\"top-left\"]::after { left: 7px; top: 7px; }\n.position-grid [data-position=\"top-right\"]::after { right: 7px; top: 7px; }\n.position-grid [data-position=\"bottom-left\"]::after { left: 7px; bottom: 7px; }\n.position-grid [data-position=\"bottom-right\"]::after { right: 7px; bottom: 7px; }\n.position-grid button.active {\n  border-color: #2d2728;\n  background: #fff7e3;\n  box-shadow: inset 0 0 0 2px #2d2728, 0 7px 14px rgba(36, 31, 33, .12);\n}\n\n.sliders label {\n  display: grid;\n  grid-template-columns: 92px 1fr;\n  align-items: center;\n  gap: 12px;\n  color: var(--soft-ink);\n  font-size: 13px;\n  font-weight: 850;\n}\ninput[type=\"range\"] {\n  width: 100%;\n  accent-color: var(--teal);\n}\n\n.actions {\n  grid-template-columns: 1fr 1fr;\n  margin-top: auto;\n}\n\n@media (max-width: 940px) {\n  .app { place-items: start center; }\n  .studio {\n    grid-template-columns: 1fr;\n  }\n  .controls {\n    display: grid;\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n    align-items: start;\n  }\n  .upload-zone,\n  .actions {\n    grid-column: 1 / -1;\n  }\n}\n\n@media (max-width: 620px) {\n  .app { padding: 10px; }\n  .workspace,\n  .controls { padding: 12px; }\n  .brand-row { align-items: center; }\n  h1 { font-size: 34px; }\n  .controls { grid-template-columns: 1fr; }\n  .actions { grid-template-columns: 1fr; }\n}\n","game.js":"const canvas = document.querySelector(\"#petCanvas\");\nconst ctx = canvas.getContext(\"2d\");\nconst app = document.querySelector(\".app\");\nconst photoInput = document.querySelector(\"#photoInput\");\nconst cameraInput = document.querySelector(\"#cameraInput\");\nconst cameraBtn = document.querySelector(\"#cameraBtn\");\nconst dropZone = document.querySelector(\"#dropZone\");\nconst emptyState = document.querySelector(\"#emptyState\");\nconst detectorStatus = document.querySelector(\"#detectorStatus\");\nconst phraseInput = document.querySelector(\"#phraseInput\");\nconst phraseBtn = document.querySelector(\"#phraseBtn\");\nconst shortBtn = document.querySelector(\"#shortBtn\");\nconst shuffleAllBtn = document.querySelector(\"#shuffleAllBtn\");\nconst moodSelect = document.querySelector(\"#moodSelect\");\nconst sizeRange = document.querySelector(\"#sizeRange\");\nconst textRange = document.querySelector(\"#textRange\");\nconst downloadBtn = document.querySelector(\"#downloadBtn\");\nconst clearBtn = document.querySelector(\"#clearBtn\");\nconst sharePhotoBtn = document.querySelector(\"#sharePhotoBtn\");\nconst shareAppBtn = document.querySelector(\"#shareAppBtn\");\n\nconst state = {\n  image: null,\n  pet: \"cat\",\n  bubble: \"thought\",\n  position: \"auto\",\n  mood: \"random\",\n  phrase: \"\",\n  size: 1,\n  textScale: 1,\n  detection: null,\n  imageFit: null,\n  warning: \"\"\n};\n\nlet detectorPromise = null;\n\nconst phrases = {\n  cat: {\n    food: [\n      \"I require snack tribute at once.\",\n      \"This bowl is tragically half-visible.\",\n      \"The cheese has been detected.\",\n      \"I licked it, so now it is mine.\",\n      \"A tiny salmon would fix everything.\",\n      \"Why is dinner late by seven seconds?\",\n      \"I am but a loaf seeking gravy.\",\n      \"Crumbs are just floor sprinkles.\"\n    ],\n    royalty: [\n      \"My kingdom has excellent sunbeams.\",\n      \"Carry me, furniture person.\",\n      \"I have pardoned the couch.\",\n      \"This carpet is my summer palace.\",\n      \"Bow gently. I am digesting.\",\n      \"The crown is invisible but heavy.\",\n      \"I approve this lap.\",\n      \"All shelves are legally mine.\"\n    ],\n    chaos: [\n      \"What if gravity needs testing?\",\n      \"The plant looked at me first.\",\n      \"Zoom meeting? I heard zoom.\",\n      \"I have hidden one sock emotionally.\",\n      \"This curtain knows too much.\",\n      \"At 3 a.m., we gallop.\",\n      \"I can fit. I have decided.\",\n      \"The tiny cup must fall.\"\n    ],\n    nap: [\n      \"I am charging my purr battery.\",\n      \"Five more hours, then breakfast.\",\n      \"This nap has a nap inside it.\",\n      \"Do not disturb the soft engine.\",\n      \"I found a sun puddle.\",\n      \"My bones are now soup.\",\n      \"Wake me when snacks become law.\",\n      \"Dreaming of forbidden counters.\"\n    ],\n    dramatic: [\n      \"No one has ever suffered like me.\",\n      \"The closed door has betrayed us.\",\n      \"I was petted only nine times.\",\n      \"The vacuum remains my oldest enemy.\",\n      \"I sing because the hallway echoes.\",\n      \"My bowl: empty in spirit.\",\n      \"A tragedy in one meow.\",\n      \"I saw the bottom of the bowl.\"\n    ],\n    compliment: [\n      \"Your lap is premium real estate.\",\n      \"You are warm and acceptable.\",\n      \"I saved my softest blink for you.\",\n      \"Your keyboard needed my help.\",\n      \"I chose you, snack wizard.\",\n      \"Today you may pet the velvet.\",\n      \"Your hoodie is now our hoodie.\",\n      \"You smell like home and toast.\"\n    ]\n  },\n  dog: {\n    food: [\n      \"Is that for us or just you?\",\n      \"I heard cheese from three rooms away.\",\n      \"My tummy has breaking news.\",\n      \"If it drops, I am ready.\",\n      \"Please admire my snack face.\",\n      \"This kibble has notes of crunch.\",\n      \"The fridge and I are close friends.\",\n      \"I pre-washed your plate with love.\"\n    ],\n    royalty: [\n      \"I am mayor of this blanket.\",\n      \"All visitors must meet my tail.\",\n      \"This yard is under my protection.\",\n      \"I hereby knight this squeaky toy.\",\n      \"My throne has suspicious crumbs.\",\n      \"I rule with kindness and drool.\",\n      \"Behold my formal sitting pose.\",\n      \"The mail has been warned.\"\n    ],\n    chaos: [\n      \"I brought you a mystery leaf.\",\n      \"My tail started it.\",\n      \"The ball is gone. Again please.\",\n      \"I found a smell from history.\",\n      \"Emergency! A squirrel-shaped rumor.\",\n      \"I will help by standing exactly here.\",\n      \"The puddle called my name.\",\n      \"This shoe wanted adventure.\"\n    ],\n    nap: [\n      \"I am dreaming in tennis balls.\",\n      \"Wake me for snacks or applause.\",\n      \"The floor is surprisingly luxurious.\",\n      \"My snores are tiny engines.\",\n      \"I worked very hard being near you.\",\n      \"This nap needs supervision.\",\n      \"I am storing sunshine for later.\",\n      \"Do not move. We are cozy.\"\n    ],\n    dramatic: [\n      \"You left for four whole minutes.\",\n      \"The bath has changed me forever.\",\n      \"I was brave near the broom.\",\n      \"My toy is under the couch forever.\",\n      \"A doorbell happened. I survived.\",\n      \"The leash is late and I noticed.\",\n      \"My ears heard betrayal: no walk yet.\",\n      \"I gave you my paw. Pay attention.\"\n    ],\n    compliment: [\n      \"You are my favorite human today.\",\n      \"Your socks smell like adventure.\",\n      \"I saved this wiggle for you.\",\n      \"Excellent job existing near me.\",\n      \"Your face is great for kisses.\",\n      \"We are best friends officially.\",\n      \"I would share my stick with you.\",\n      \"You make the couch better.\"\n    ]\n  },\n  either: {\n    food: [\n      \"Tiny treat? Big emotional recovery.\",\n      \"I believe snacks are a love language.\",\n      \"The kitchen has possibilities.\",\n      \"I can hear a wrapper thinking.\",\n      \"Please submit one crumb for testing.\",\n      \"A small bite would improve science.\",\n      \"My bowl and I are in talks.\",\n      \"I have never eaten, probably.\"\n    ],\n    royalty: [\n      \"I own this sunbeam now.\",\n      \"This blanket is my tiny estate.\",\n      \"The household is running smoothly.\",\n      \"My staff is cute but slow.\",\n      \"Please schedule my admiration.\",\n      \"I am dressed in natural elegance.\",\n      \"This spot has been claimed.\",\n      \"A noble fluff surveys the realm.\"\n    ],\n    chaos: [\n      \"What if we made this weird?\",\n      \"I found a noise and chased it.\",\n      \"This object could be elsewhere.\",\n      \"I am helping in a confusing way.\",\n      \"Adventure smells slightly dusty.\",\n      \"No plan, only sparkle.\",\n      \"The floor knows what happened.\",\n      \"I regret nothing except bath time.\"\n    ],\n    nap: [\n      \"I am busy being a warm potato.\",\n      \"This blink became a meeting.\",\n      \"Saving energy for more cuteness.\",\n      \"Nap level: expert deluxe.\",\n      \"I have melted into this spot.\",\n      \"My dream has snacks in it.\",\n      \"Cozy mode cannot be canceled.\",\n      \"This is professional resting.\"\n    ],\n    dramatic: [\n      \"I was ignored for almost moments.\",\n      \"History will remember this empty bowl.\",\n      \"The door is closed. Society has failed.\",\n      \"I am small, but my feelings are huge.\",\n      \"A betrayal, possibly involving shampoo.\",\n      \"The blanket moved without permission.\",\n      \"I have concerns and one whisker.\",\n      \"My patience is ornamental.\"\n    ],\n    compliment: [\n      \"You are my favorite furniture.\",\n      \"Your voice is my cozy sound.\",\n      \"Good human. Very good human.\",\n      \"I made this face just for you.\",\n      \"You are part of my collection.\",\n      \"Thanks for being my warm thing.\",\n      \"I trust you with my weirdness.\",\n      \"We are a very cute team.\"\n    ]\n  }\n};\n\nconst shortPhrases = [\n  \"Snack?\",\n  \"Boop me.\",\n  \"I am baby.\",\n  \"More cozy.\",\n  \"Tiny chaos.\",\n  \"Best day.\",\n  \"I helped.\",\n  \"Treat tax.\",\n  \"Nap boss.\",\n  \"Very wow.\",\n  \"Me? Never.\",\n  \"Soft plans.\"\n];\n\nfunction allMoodKeys() {\n  return [\"food\", \"royalty\", \"chaos\", \"nap\", \"dramatic\", \"compliment\"];\n}\n\nfunction pick(array) {\n  return array[Math.floor(Math.random() * array.length)];\n}\n\nfunction nextPhrase(short = false) {\n  if (state.warning) {\n    state.phrase = state.warning;\n    phraseInput.value = state.phrase;\n    draw();\n    return;\n  }\n  if (short) {\n    state.phrase = pick(shortPhrases);\n  } else {\n    const pet = state.pet;\n    const mood = state.mood === \"random\" ? pick(allMoodKeys()) : state.mood;\n    state.phrase = pick(phrases[pet][mood]);\n  }\n  phraseInput.value = state.phrase;\n  draw();\n}\n\nfunction draw() {\n  const width = canvas.width;\n  const height = canvas.height;\n  ctx.clearRect(0, 0, width, height);\n\n  if (state.image) {\n    drawCoverImage(state.image, width, height);\n    drawBubble(width, height);\n  } else {\n    drawPlaceholder(width, height);\n  }\n}\n\nfunction setPhotoVisible(hasPhoto) {\n  app.classList.toggle(\"has-photo\", hasPhoto);\n}\n\nfunction drawCoverImage(image, width, height) {\n  const canvasRatio = width / height;\n  const imageRatio = image.naturalWidth / image.naturalHeight;\n  let sourceWidth = image.naturalWidth;\n  let sourceHeight = image.naturalHeight;\n  let sourceX = 0;\n  let sourceY = 0;\n\n  if (imageRatio > canvasRatio) {\n    sourceWidth = image.naturalHeight * canvasRatio;\n    sourceX = (image.naturalWidth - sourceWidth) / 2;\n  } else {\n    sourceHeight = image.naturalWidth / canvasRatio;\n    sourceY = (image.naturalHeight - sourceHeight) / 2;\n  }\n\n  state.imageFit = { sourceX, sourceY, sourceWidth, sourceHeight, width, height };\n  ctx.drawImage(image, sourceX, sourceY, sourceWidth, sourceHeight, 0, 0, width, height);\n}\n\nfunction drawPlaceholder(width, height) {\n  const gradient = ctx.createLinearGradient(0, 0, width, height);\n  gradient.addColorStop(0, \"#fff5d8\");\n  gradient.addColorStop(.58, \"#f2ebe1\");\n  gradient.addColorStop(1, \"#dff3ef\");\n  ctx.fillStyle = gradient;\n  ctx.fillRect(0, 0, width, height);\n\n  ctx.fillStyle = \"rgba(45, 39, 40, .08)\";\n  for (let y = 0; y < height; y += 96) {\n    for (let x = 0; x < width; x += 96) {\n      ctx.beginPath();\n      ctx.arc(x + 38, y + 34, 12, 0, Math.PI * 2);\n      ctx.arc(x + 68, y + 34, 12, 0, Math.PI * 2);\n      ctx.arc(x + 52, y + 58, 18, 0, Math.PI * 2);\n      ctx.fill();\n    }\n  }\n}\n\nfunction drawBubble(width, height) {\n  const phrase = (state.phrase || \"I am thinking extremely important fluff thoughts.\").trim();\n  const scale = state.size;\n  const margin = 54;\n  const bubbleWidth = Math.min(width - margin * 2, 470 * scale);\n  const baseFont = Math.round(38 * state.textScale);\n  const lines = wrapText(phrase, bubbleWidth - 76, baseFont);\n  const bubbleHeight = Math.max(160 * scale, lines.length * baseFont * 1.18 + 74);\n  const pos = bubblePosition(width, height, bubbleWidth, bubbleHeight, margin);\n\n  ctx.save();\n  ctx.shadowColor = \"rgba(36, 31, 33, .28)\";\n  ctx.shadowBlur = 24;\n  ctx.shadowOffsetY = 10;\n  ctx.fillStyle = \"#ffffff\";\n  ctx.strokeStyle = \"#2d2728\";\n  ctx.lineWidth = 7;\n\n  if (state.bubble === \"speech\") {\n    speechTail(pos);\n  } else {\n    thoughtDots(pos);\n  }\n\n  roundedRect(pos.x, pos.y, bubbleWidth, bubbleHeight, 42);\n  ctx.fill();\n  ctx.stroke();\n  ctx.restore();\n\n  ctx.fillStyle = \"#211d1e\";\n  ctx.font = `900 ${baseFont}px ui-sans-serif, system-ui, -apple-system, Segoe UI, Arial`;\n  ctx.textAlign = \"center\";\n  ctx.textBaseline = \"middle\";\n\n  const lineHeight = baseFont * 1.18;\n  const firstY = pos.y + bubbleHeight / 2 - ((lines.length - 1) * lineHeight) / 2;\n  lines.forEach((line, index) => {\n    ctx.fillText(line, pos.x + bubbleWidth / 2, firstY + index * lineHeight);\n  });\n}\n\nfunction bubblePosition(width, height, bubbleWidth, bubbleHeight, margin) {\n  if (state.position === \"auto\" && state.detection && state.imageFit) {\n    return autoBubblePosition(width, height, bubbleWidth, bubbleHeight, margin);\n  }\n\n  const xRight = width - bubbleWidth - margin;\n  const yBottom = height - bubbleHeight - margin;\n  const positions = {\n    \"top-left\": { x: margin, y: margin, width: bubbleWidth, height: bubbleHeight, anchorX: margin + bubbleWidth * .24, anchorY: margin + bubbleHeight },\n    \"top-right\": { x: xRight, y: margin, width: bubbleWidth, height: bubbleHeight, anchorX: xRight + bubbleWidth * .76, anchorY: margin + bubbleHeight },\n    \"bottom-left\": { x: margin, y: yBottom, width: bubbleWidth, height: bubbleHeight, anchorX: margin + bubbleWidth * .24, anchorY: yBottom },\n    \"bottom-right\": { x: xRight, y: yBottom, width: bubbleWidth, height: bubbleHeight, anchorX: xRight + bubbleWidth * .76, anchorY: yBottom }\n  };\n  return positions[state.position] || positions[\"top-right\"];\n}\n\nfunction autoBubblePosition(width, height, bubbleWidth, bubbleHeight, margin) {\n  const target = headTarget();\n  const leftSpace = target.x;\n  const rightSpace = width - target.x;\n  const topSpace = target.y;\n  const bottomSpace = height - target.y;\n  const preferTop = topSpace > bubbleHeight + 95 || topSpace >= bottomSpace;\n  const preferLeft = leftSpace > rightSpace;\n  const x = clamp(preferLeft ? target.x - bubbleWidth - 70 : target.x + 70, margin, width - bubbleWidth - margin);\n  const y = clamp(preferTop ? target.y - bubbleHeight - 70 : target.y + 70, margin, height - bubbleHeight - margin);\n\n  return {\n    x,\n    y,\n    width: bubbleWidth,\n    height: bubbleHeight,\n    anchorX: clamp(target.x, x + 48, x + bubbleWidth - 48),\n    anchorY: y + bubbleHeight / 2,\n    targetX: target.x,\n    targetY: target.y\n  };\n}\n\nfunction headTarget() {\n  const box = detectionToCanvasBox(state.detection);\n  const petHeadY = state.pet === \"dog\" ? .31 : .27;\n  return {\n    x: clamp(box.x + box.w * .5, 28, canvas.width - 28),\n    y: clamp(box.y + box.h * petHeadY, 28, canvas.height - 28)\n  };\n}\n\nfunction detectionToCanvasBox(detection) {\n  const fit = state.imageFit;\n  const [x, y, w, h] = detection.bbox;\n  const left = (x - fit.sourceX) / fit.sourceWidth * fit.width;\n  const top = (y - fit.sourceY) / fit.sourceHeight * fit.height;\n  const width = w / fit.sourceWidth * fit.width;\n  const height = h / fit.sourceHeight * fit.height;\n  return {\n    x: clamp(left, 0, fit.width),\n    y: clamp(top, 0, fit.height),\n    w: clamp(width, 0, fit.width),\n    h: clamp(height, 0, fit.height)\n  };\n}\n\nfunction speechTail(pos) {\n  if (pos.targetX !== undefined) {\n    ctx.beginPath();\n    const baseX = clamp(pos.targetX, pos.x + 62, pos.x + pos.width - 62);\n    const baseY = clamp(pos.targetY < pos.y ? pos.y + 14 : pos.y + pos.height - 14, pos.y + 14, pos.y + pos.height - 14);\n    ctx.moveTo(baseX - 52, baseY);\n    ctx.lineTo(baseX + 52, baseY);\n    ctx.lineTo(pos.targetX, pos.targetY);\n    ctx.closePath();\n    ctx.fill();\n    ctx.stroke();\n    return;\n  }\n\n  const down = pos.y < canvas.height / 2;\n  const tipY = down ? pos.y + 172 : pos.y - 92;\n  const baseY = down ? pos.y + 120 : pos.y + 18;\n  ctx.beginPath();\n  ctx.moveTo(pos.anchorX - 38, baseY);\n  ctx.lineTo(pos.anchorX + 86, baseY + (down ? 8 : -8));\n  ctx.lineTo(pos.anchorX + 12, tipY);\n  ctx.closePath();\n  ctx.fill();\n  ctx.stroke();\n}\n\nfunction thoughtDots(pos) {\n  if (pos.targetX !== undefined) {\n    const dx = (pos.targetX - pos.anchorX) / 4;\n    const dy = (pos.targetY - pos.anchorY) / 4;\n    [\n      { r: 16, step: 3.1 },\n      { r: 25, step: 2.05 },\n      { r: 36, step: 1.05 }\n    ].forEach((dot) => {\n      ctx.beginPath();\n      ctx.arc(pos.anchorX + dx * dot.step, pos.anchorY + dy * dot.step, dot.r, 0, Math.PI * 2);\n      ctx.fill();\n      ctx.stroke();\n    });\n    return;\n  }\n\n  const down = pos.y < canvas.height / 2;\n  const dots = [\n    { r: 18, dx: 14, dy: down ? 36 : -36 },\n    { r: 28, dx: 54, dy: down ? 78 : -78 },\n    { r: 40, dx: 102, dy: down ? 126 : -126 }\n  ];\n  dots.forEach((dot) => {\n    ctx.beginPath();\n    ctx.arc(pos.anchorX + dot.dx, pos.anchorY + dot.dy, dot.r, 0, Math.PI * 2);\n    ctx.fill();\n    ctx.stroke();\n  });\n}\n\nfunction roundedRect(x, y, width, height, radius) {\n  ctx.beginPath();\n  ctx.moveTo(x + radius, y);\n  ctx.arcTo(x + width, y, x + width, y + height, radius);\n  ctx.arcTo(x + width, y + height, x, y + height, radius);\n  ctx.arcTo(x, y + height, x, y, radius);\n  ctx.arcTo(x, y, x + width, y, radius);\n  ctx.closePath();\n}\n\nfunction wrapText(text, maxWidth, fontSize) {\n  ctx.font = `900 ${fontSize}px ui-sans-serif, system-ui, -apple-system, Segoe UI, Arial`;\n  const words = text.split(/\\s+/).filter(Boolean);\n  const lines = [];\n  let line = \"\";\n\n  words.forEach((word) => {\n    const test = line ? `${line} ${word}` : word;\n    if (ctx.measureText(test).width <= maxWidth || !line) {\n      line = test;\n    } else {\n      lines.push(line);\n      line = word;\n    }\n  });\n  if (line) lines.push(line);\n  return lines.slice(0, 4);\n}\n\nfunction clamp(value, min, max) {\n  return Math.min(max, Math.max(min, value));\n}\n\nfunction loadFile(file) {\n  if (!file || !file.type.startsWith(\"image/\")) return;\n  const reader = new FileReader();\n  reader.addEventListener(\"load\", () => {\n    const image = new Image();\n    image.addEventListener(\"load\", () => {\n      state.image = image;\n      state.detection = null;\n      state.warning = \"\";\n      setPhotoVisible(true);\n      emptyState.classList.add(\"hidden\");\n      nextPhrase();\n      identifyPet(image);\n    });\n    image.src = reader.result;\n  });\n  reader.readAsDataURL(file);\n}\n\nphotoInput.addEventListener(\"change\", (event) => loadFile(event.target.files[0]));\ncameraInput.addEventListener(\"change\", (event) => loadFile(event.target.files[0]));\ncameraBtn.addEventListener(\"keydown\", (event) => {\n  if (event.key === \"Enter\" || event.key === \" \") {\n    event.preventDefault();\n    cameraInput.click();\n  }\n});\n\n[\"dragenter\", \"dragover\"].forEach((type) => {\n  dropZone.addEventListener(type, (event) => {\n    event.preventDefault();\n    dropZone.classList.add(\"dragover\");\n  });\n});\n[\"dragleave\", \"drop\"].forEach((type) => {\n  dropZone.addEventListener(type, (event) => {\n    event.preventDefault();\n    dropZone.classList.remove(\"dragover\");\n  });\n});\ndropZone.addEventListener(\"drop\", (event) => loadFile(event.dataTransfer.files[0]));\n\ndocument.querySelectorAll(\"[data-pet]\").forEach((button) => {\n  button.addEventListener(\"click\", () => {\n    state.pet = button.dataset.pet;\n    state.warning = \"\";\n    document.querySelectorAll(\"[data-pet]\").forEach((item) => item.classList.toggle(\"active\", item === button));\n    nextPhrase();\n  });\n});\n\ndocument.querySelectorAll(\"[data-bubble]\").forEach((button) => {\n  button.addEventListener(\"click\", () => {\n    state.bubble = button.dataset.bubble;\n    document.querySelectorAll(\"[data-bubble]\").forEach((item) => item.classList.toggle(\"active\", item === button));\n    draw();\n  });\n});\n\ndocument.querySelectorAll(\"[data-position]\").forEach((button) => {\n  button.addEventListener(\"click\", () => {\n    state.position = button.dataset.position;\n    document.querySelectorAll(\"[data-position]\").forEach((item) => item.classList.toggle(\"active\", item === button));\n    draw();\n  });\n});\n\nmoodSelect.addEventListener(\"change\", () => {\n  state.mood = moodSelect.value;\n  nextPhrase();\n});\nphraseInput.addEventListener(\"input\", () => {\n  state.phrase = phraseInput.value;\n  draw();\n});\nsizeRange.addEventListener(\"input\", () => {\n  state.size = Number(sizeRange.value) / 100;\n  draw();\n});\ntextRange.addEventListener(\"input\", () => {\n  state.textScale = Number(textRange.value) / 100;\n  draw();\n});\nphraseBtn.addEventListener(\"click\", () => nextPhrase());\nshortBtn.addEventListener(\"click\", () => nextPhrase(true));\nshuffleAllBtn.addEventListener(\"click\", () => {\n  state.pet = pick([\"cat\", \"dog\", \"either\"]);\n  state.bubble = pick([\"thought\", \"speech\"]);\n  state.position = state.detection ? \"auto\" : pick([\"auto\", \"top-left\", \"top-right\", \"bottom-left\", \"bottom-right\"]);\n  state.mood = \"random\";\n  moodSelect.value = \"random\";\n  document.querySelectorAll(\"[data-pet]\").forEach((item) => item.classList.toggle(\"active\", item.dataset.pet === state.pet));\n  document.querySelectorAll(\"[data-bubble]\").forEach((item) => item.classList.toggle(\"active\", item.dataset.bubble === state.bubble));\n  document.querySelectorAll(\"[data-position]\").forEach((item) => item.classList.toggle(\"active\", item.dataset.position === state.position));\n  nextPhrase();\n});\n\ndownloadBtn.addEventListener(\"click\", () => {\n  downloadImage();\n});\n\nsharePhotoBtn.addEventListener(\"click\", async () => {\n  if (!state.image) return;\n  const blob = await canvasBlob();\n  const file = new File([blob], \"pet-thought-bubble.png\", { type: \"image/png\" });\n\n  try {\n    if (navigator.canShare?.({ files: [file] })) {\n      await navigator.share({\n        files: [file],\n        title: \"Pet Thought Bubbler\",\n        text: \"Look what my pet is thinking.\"\n      });\n      return;\n    }\n  } catch (error) {\n    if (error.name === \"AbortError\") return;\n  }\n\n  downloadImage();\n  setDetectorStatus(\"Sharing photos is not available here, so I downloaded it instead.\", \"warning\");\n});\n\nshareAppBtn.addEventListener(\"click\", async () => {\n  const shareData = {\n    title: \"Pet Thought Bubbler\",\n    text: \"Add silly thought bubbles to cat and dog photos.\",\n    url: window.location.href\n  };\n\n  try {\n    if (navigator.share) {\n      await navigator.share(shareData);\n      return;\n    }\n  } catch (error) {\n    if (error.name === \"AbortError\") return;\n  }\n\n  await navigator.clipboard?.writeText(window.location.href);\n  setDetectorStatus(\"App link copied.\", \"success\");\n});\n\nclearBtn.addEventListener(\"click\", () => {\n  state.image = null;\n  state.detection = null;\n  state.warning = \"\";\n  state.phrase = \"\";\n  phraseInput.value = \"\";\n  photoInput.value = \"\";\n  cameraInput.value = \"\";\n  setPhotoVisible(false);\n  setDetectorStatus(\"Ready to spot cats and dogs.\");\n  emptyState.classList.remove(\"hidden\");\n  draw();\n});\n\ndraw();\n\nfunction downloadImage() {\n  const link = document.createElement(\"a\");\n  link.download = \"pet-thought-bubble.png\";\n  link.href = canvas.toDataURL(\"image/png\");\n  link.click();\n}\n\nfunction canvasBlob() {\n  return new Promise((resolve) => canvas.toBlob(resolve, \"image/png\"));\n}\n\nasync function identifyPet(image) {\n  setDetectorStatus(\"Looking for a cat or dog...\");\n  try {\n    const detector = await loadDetector();\n    const predictions = await detector.detect(image);\n    const pets = predictions.filter((item) => [\"cat\", \"dog\"].includes(item.class) && item.score >= .45);\n    const people = predictions.filter((item) => item.class === \"person\" && item.score >= .5);\n\n    if (pets.length) {\n      const pet = pets.sort((a, b) => scoreDetection(b) - scoreDetection(a))[0];\n      state.pet = pet.class;\n      state.detection = pet;\n      state.warning = \"\";\n      setActivePet(pet.class);\n      setDetectorStatus(`Looks like a ${pet.class}. Bubble aligned near the head.`, \"success\");\n      nextPhrase();\n      return;\n    }\n\n    if (people.length) {\n      state.pet = \"either\";\n      state.detection = null;\n      state.warning = \"That's not a pet. Try a cat or dog photo.\";\n      setActivePet(\"either\");\n      setDetectorStatus(\"That's not a pet. Try a cat or dog photo.\", \"warning\");\n      nextPhrase();\n      return;\n    }\n\n    state.detection = null;\n    state.warning = \"I can't find a cat or dog yet. Try a clearer pet photo.\";\n    setDetectorStatus(\"I can't find a cat or dog yet. Try a clearer pet photo.\", \"warning\");\n    nextPhrase();\n  } catch (error) {\n    state.detection = null;\n    setDetectorStatus(\"Pet spotting is unavailable right now, but you can still make bubbles manually.\", \"warning\");\n    draw();\n  }\n}\n\nfunction loadDetector() {\n  if (!detectorPromise) {\n    detectorPromise = new Promise((resolve, reject) => {\n      const startedAt = Date.now();\n      const waitForModel = () => {\n        if (window.cocoSsd) {\n          window.cocoSsd.load().then(resolve, reject);\n        } else if (Date.now() - startedAt > 10000) {\n          reject(new Error(\"Detector did not load\"));\n        } else {\n          window.setTimeout(waitForModel, 120);\n        }\n      };\n      waitForModel();\n    });\n  }\n  return detectorPromise;\n}\n\nfunction scoreDetection(item) {\n  return item.score * item.bbox[2] * item.bbox[3];\n}\n\nfunction setActivePet(pet) {\n  document.querySelectorAll(\"[data-pet]\").forEach((item) => item.classList.toggle(\"active\", item.dataset.pet === pet));\n}\n\nfunction setDetectorStatus(message, tone = \"\") {\n  detectorStatus.textContent = message;\n  detectorStatus.classList.toggle(\"success\", tone === \"success\");\n  detectorStatus.classList.toggle(\"warning\", tone === \"warning\");\n}\n"};

const contentTypes = {
  "index.html": "text/html; charset=utf-8",
  "styles.css": "text/css; charset=utf-8",
  "game.js": "text/javascript; charset=utf-8"
};

export default {
  async fetch(request) {
    const url = new URL(request.url);
    let path = decodeURIComponent(url.pathname);

    if (path === "/" || path === "") {
      path = "/index.html";
    }

    const key = path.replace(/^\//, "");
    const body = files[key];

    if (!body) {
      return new Response(files["index.html"], {
        headers: {
          "content-type": contentTypes["index.html"],
          "cache-control": "no-store"
        }
      });
    }

    return new Response(body, {
      headers: {
        "content-type": contentTypes[key] || "application/octet-stream",
        "cache-control": "no-store"
      }
    });
  }
};
